import 'package:flutter/material.dart'; import 'package:flutter_riverpod/flutter_riverpod.dart'; import 'package:go_router/go_router.dart'; import '../../../../shared/providers/auth_provider.dart'; import '../../../products/presentation/providers.dart'; import '../../../products/presentation/widgets/product_card.dart'; import '../../../surplus/presentation/screens/surplus_screen.dart';
class InternationalDashboard extends ConsumerWidget{const InternationalDashboard({super.key});@override Widget build(BuildContext c,WidgetRef ref){final user=ref.watch(authProvider).user;final p=ref.watch(exportProductsProvider);return Scaffold(appBar:AppBar(title:const Text('International Marketplace'),actions:[IconButton(onPressed:()async{await ref.read(authProvider.notifier).logout();if(c.mounted)c.go('/login');},icon:const Icon(Icons.logout))]),body:RefreshIndicator(onRefresh:()=>ref.refresh(exportProductsProvider.future),child:ListView(padding:const EdgeInsets.all(16),children:[Text('Welcome ${user?.name??'International Buyer'} 🌎',style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:12),const Text('Export products appear when the surplus rule activates.'),const SizedBox(height:16),FilledButton.icon(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const SurplusScreen())),icon:const Icon(Icons.analytics),label:const Text('View Market Status')),const SizedBox(height:20),...p.when(data:(items)=>items.isEmpty?[const Center(child:Padding(padding:EdgeInsets.all(30),child:Text('No export products available right now.')))]:(items.map((x)=>ProductCard(product:x)).toList()),loading:()=>[const Center(child:CircularProgressIndicator())],error:(e,_)=>[Text('Error: $e')])])));}}
